def merge_sorted_streams(*streams):
    iterators = [iter(stream) for stream in streams]
    current = []
    for i, it in enumerate(iterators):
        try:
            current.append((it.__next__(), i))
        except StopIteration:
            current.append(None)

    while any(item is not None for item in current):
        min_key = None
        min_index = None
        for i, item in enumerate(current):
            if item is not None:
                key = item[0][0]
                if min_key is None or key < min_key or (key == min_key and i > min_index):
                    min_key = key
                    min_index = i

        if min_index is None:
            break

        key, value = current[min_index][0]
        current[min_index] = None

        try:
            next_item = iterators[min_index].__next__()
            if next_item[0] == key:
                current[min_index] = (next_item, min_index)
            else:
                current[min_index] = (next_item, min_index)
        except StopIteration:
            pass

        yield (key, value)
